type ProviderPurpose = 'claude' | 'codex' | 'cursor' | 'verifier';
type ChildPurpose =
  | ProviderPurpose
  | 'devServer'
  | 'packageManager'
  | 'profileMemory'
  | 'git'
  | 'github'
  | 'desktop';
type SubprocessPurpose = ChildPurpose | 'rivetRuntime';

interface EnvironmentAllowlist {
  names: readonly string[];
  prefixes: readonly string[];
}

