const childAllowlists = Object.values(CHILD_ALLOWLISTS);

const ALLOWLISTS: Record<SubprocessPurpose, EnvironmentAllowlist> = {
  ...CHILD_ALLOWLISTS,
  rivetRuntime: {
    names: [
      ...childAllowlists.flatMap((allowlist) => allowlist.names),
      ...RIVET_RUNTIME_VARIABLES,
    ],
    prefixes: [
      ...childAllowlists.flatMap((allowlist) => allowlist.prefixes),
      ...RIVET_PREFIXES,
    ],
  },
};

const hasAllowedPrefix = (
  name: string,
  prefixes: readonly string[],
): boolean => {
  const normalizedName = name.toLowerCase();
  return prefixes.some((prefix) =>
    normalizedName.startsWith(prefix.toLowerCase()),
  );
};

export const subprocessEnvironment = (
  purpose: SubprocessPurpose,
  inherited: NodeJS.ProcessEnv = process.env,
): NodeJS.ProcessEnv => {
  const { names, prefixes } = ALLOWLISTS[purpose];
  const environment: NodeJS.ProcessEnv = {};
  const allowedNames = new Set(names.map((name) => name.toLowerCase()));
  for (const [name, value] of Object.entries(inherited)) {
    if (
      value !== undefined &&
      (allowedNames.has(name.toLowerCase()) || hasAllowedPrefix(name, prefixes))
    )
      environment[name] = value;
  }
  return environment;
};
